package com.example.starter.incident;

/**
 * 互助租约状态。
 * OPEN：未结清（仍有待归还数量；租约到期但未还完时仍保持 OPEN，到期不自动虚构归还）。
 * CLOSED：分次归还累计恰好等于征调总量后关闭，终态；关闭时不再次释放来源额度。
 */
public enum LeaseStatus {
    OPEN,
    CLOSED
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 事件互助资源台账实体，对应 incident_resource_inventories 表（来源事件侧）。
 * 数量单位为件（非负整数）；totalQty 登记后不变，availableQty 随征调扣减、归还返还，
 * 恒满足 0 ≤ availableQty ≤ totalQty。时间均为 UTC。
 */
public record ResourceInventory(
        long id,
        long incidentId,
        String resourceCode,
        long totalQty,
        long availableQty,
        Instant createdAt,
        Instant updatedAt) {
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 跨事件互助资源租约实体，对应 incident_resource_leases 表（目标事件侧）。
 * requestId 全局唯一，同键同参重放首次双侧账务结果，同键改数量或目标事件返回 409；
 * quantity 为征调总量（正整数，件），returnedQty 为分次归还累计量，
 * 恒满足 0 ≤ returnedQty ≤ quantity；到期时刻 expiresAt 仅为元数据，
 * 到期不产生自动归还；closedAt 仅在最后一次归还恰好结清时（CLOSED）有值。
 * sourceIncidentId/targetIncidentId 落库后永不改变，历史租约保留首次征调两端事件。
 */
public record ResourceLease(
        long id,
        String requestId,
        long sourceIncidentId,
        long targetIncidentId,
        String resourceCode,
        long quantity,
        long returnedQty,
        LeaseStatus status,
        Instant expiresAt,
        Instant closedAt,
        Instant createdAt,
        Instant updatedAt) {

    /** 待归还数量（件）：征调总量减已归还累计量。 */
    public long outstandingQty() {
        return quantity - returnedQty;
    }
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 互助租约分次归还流水实体，对应 incident_resource_returns 表。
 * 每条记录一次实际归还：quantity 为本件数（正整数），returnedBy 为归还人
 * （归还时目标事件的当前指挥人），returnedAt/createdAt 均为 UTC。
 * requestId 全局唯一，同键同参重放首次流水结果，同键改参返回 409。
 */
public record ResourceReturn(
        long id,
        long leaseId,
        String requestId,
        long quantity,
        String returnedBy,
        Instant returnedAt,
        Instant createdAt) {
}

