        assertThat(closed.returnedQty()).isEqualTo(3);
        assertThat(closed.outstandingQty()).isZero();
        assertThat(closed.closedAt()).isEqualTo(T0);
        assertThat(availableOf("INC-A", "R")).isEqualTo(5L);

